<?php declare(strict_types=1); require __DIR__.'/lib/bootstrap.php'; require __DIR__.'/lib/layout.php'; require_permission('audit.read');$rows=db()->query('SELECT a.*,u.display_name FROM cms_audit_logs a LEFT JOIN cms_users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 200')->fetchAll();page_start('Audit Log','audit');?><div class="page-head"><div><span class="eyebrow">SECURITY</span><h2>Audit log</h2><p class="muted">A chronological record of administrative activity.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['created_at'])?></td><td><?=e($row['display_name']??'System')?></td><td><code><?=e($row['action'])?></code></td><td><?=e($row['entity'])?> <?=e($row['entity_id']??'')?></td><td><?=e($row['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php page_end();
